matcher_spec:
// LIKE matcher — reproduces every pin bit-exactly against DuckDB 1.5.5 native tables.
// UNIT: literal chars and '%' operate on BYTES (patterns are valid UTF-8, so multibyte
//   literals match byte-by-byte and '%' cut points cannot mis-align lead bytes);
//   '_' consumes exactly ONE UTF-8 CODEPOINT of the string (1-4 bytes by lead byte).
//   No normalization anywhere (NFC != NFD), no graphemes, no UTF-16 units.
// NULL: s NULL || p NULL || escape NULL  =>  NULL, BEFORE any validation
//   (a NULL row never raises, even with a dangling escape or 2-byte ESCAPE string).
// ESCAPE string: validated per evaluated row: byte_len(esc_str) > 1 => Err(InvalidEscape)
//   ("Invalid escape string. Escape string must be empty or one character." — note: one
//   BYTE; a single 2-byte codepoint is rejected). Empty => no escape. Escape may come
//   from a column. NOT LIKE = !like(...) with NULL passthrough.
// ILIKE: fold BOTH sides per-codepoint with DuckDB lower()'s casemap (length-preserving,
//   includes singletons U+212A->k, U+0130->i, U+1E9E->df) and run the same matcher on the
//   folded strings ('_' then counts folded codepoints). This is DuckDB's generic path,
//   exhaustively verified over all codepoints. CAVEAT (measured): when the string
//   column's stats are pure-ASCII DuckDB silently switches to an ASCII-only fold, whose
//   ONLY observable difference is patterns containing U+212A or U+0130 — see ilike_verdict.
//   (Unmeasured corner: ILIKE with an UPPERCASE-LETTER escape char; restrict or measure.)

enum LikeErr { DanglingEscape, InvalidEscape }   // both map to DuckDB SyntaxException

fn like(s: &[u8], p: &[u8], esc: Option<u8>) -> Result<bool, LikeErr> {
    like_at(s, 0, p, 0, esc)
}

fn like_at(s: &[u8], mut si: usize, p: &[u8], mut pi: usize, esc: Option<u8>)
    -> Result<bool, LikeErr>
{
    while pi < p.len() {
        let pc = p[pi];
        if Some(pc) == esc {
            // Escape check FIRST — it beats '%' and '_' (ESCAPE '%' turns '%%' into a
            // literal percent; an unescaped escape char NEVER matches itself:
            // 'aeb' LIKE 'aeb' ESCAPE 'e' == false).
            if si == s.len() { return Ok(false); }         // exhausted string: plain false
                                                            // ('ab' LIKE 'ab#' ESC '#')
            pi += 1;
            if pi == p.len() { return Err(LikeErr::DanglingEscape); }
            // ^ raised ONLY here: i.e. only when string chars remain — data-dependent,
            //   exactly DuckDB ('ax' LIKE 'a#' ESC '#' errors, 'a' LIKE 'a#' is false).
            if s[si] != p[pi] { return Ok(false); }         // escaped char (special or
            si += 1; pi += 1;                               // not) is a literal byte
        } else if pc == b'%' {
            while pi < p.len() && p[pi] == b'%' { pi += 1; } // collapse bare-% runs
            if pi == p.len() { return Ok(true); }
            // Semantics: try suffix starts left-to-right; errors propagate from the
            // FIRST tried position (leftmost si), preserving DuckDB's error rows.
            // Implement with the iterative two-pointer restart (remember last '%' pos
            // and restart si+1) => worst case O(len(s)*len(p)). DuckDB's own
            // column-pattern path is naive-recursive O(n^k) (measured 23 s for one
            // 256-char row vs '%a%a%a%a%a') — booleans identical, never copy the blowup.
            for start in si..=s.len() {
                match like_at(s, start, p, pi, esc)? {
                    true => return Ok(true),
                    false => {}
                }
            }
            return Ok(false);
        } else if pc == b'_' {
            if si == s.len() { return Ok(false); }
            si += utf8_len(s[si]);                          // ONE codepoint: 1,2,3,4 by
            pi += 1;                                        // lead byte (0xxx/110/1110/11110)
        } else {
            if si == s.len() || s[si] != pc { return Ok(false); }
            si += 1; pi += 1;                               // raw byte compare, case-
        }                                                   // sensitive, no specials
    }
    Ok(si == s.len())                                       // '' LIKE '' == true
}
